<script setup lang="ts">
import {computed,nextTick,onMounted,ref,watch} from 'vue'
import {asset} from '../lib/assets'
import {api} from '../lib/api'
import SettingsFlow from './SettingsFlow.vue'
import MomentsFlow from './MomentsFlow.vue'
import {t} from '../lib/i18n'
import ChatFlow from './ChatFlow.vue'
const props=defineProps<{token:string;person?:{id:string;displayName:string;avatar?:string;status:string;following?:boolean;city?:string;age?:number;zodiac?:string;bio?:string;cards?:string[];moments?:{id:string;text:string;src:string}[]}}>()
const emit=defineEmits<{close:[];security:[];chat:[];safety:[action:'report'|'block']}>()
type Photo={id:string;src:string;position:number}
const key=`maugo-profile-${props.token}`
const initial={name:'Little wanderer',age:24,city:'Somewhere',zodiac:'',bio:'',slots:[1,2,3,4].map((n,i)=>({id:`portrait-${n}`,src:asset(`05-avatars/portrait-${n}`),position:i})).concat(Array(4).fill(null)) as (Photo|null)[],selected:'portrait-1',archive:[] as Photo[],cards:[] as string[]}
const profile=ref<typeof initial>(JSON.parse(localStorage.getItem(key)||'null')||initial)
watch(profile,v=>localStorage.setItem(key,JSON.stringify(v)),{deep:true})
const settingsOpen=ref(false)
const draft=ref({...profile.value}),view=ref(props.person?'public':'profile'),sheet=ref(''),error=ref(''),notice=ref(''),kind=ref('Following'),outgoing=ref(false),remove=ref(-1),position=ref(0),zoom=ref(1),canvas=ref<HTMLCanvasElement>(),file=ref<HTMLInputElement>(),image=ref<HTMLImageElement>(),followed=ref(!!props.person?.following),busy=ref(false),largePhoto=ref('')
const own=computed(()=>profile.value.slots.find(p=>p?.id===profile.value.selected)?.src||asset('05-avatars/avatar-placeholder'))
const photo=computed(()=>props.person?.avatar||asset('05-avatars/avatar-placeholder'))
type Connection={id:string;displayName:string;avatar?:string;status:string;following?:boolean}
const connections=ref<Connection[]>([]),letters=ref<string[]>([]),selectedPerson=ref<Connection>(),selectedChat=ref<Connection>(),loading=ref(false)
const following=computed(()=>connections.value.filter(c=>c.following))
const visits=ref<Connection[]>(JSON.parse(localStorage.getItem(key+'-visits')||'[]'))
watch(visits,v=>localStorage.setItem(key+'-visits',JSON.stringify(v)),{deep:true})
async function load(){if(!props.token||props.person)return;loading.value=true;try{const all:Connection[]=[];for(let offset=0;;offset+=100){const r=await api<{items:Connection[];hasMore?:boolean}>(`/conversations?tab=messages&hidden=false&limit=100&offset=${offset}`,{headers:{Authorization:`Bearer ${props.token}`}});all.push(...r.items);if(!r.hasMore&&r.items.length<100)break}connections.value=all;const rows=await Promise.all(all.map(c=>api<{items:{content:string;kind:string;mine:boolean}[]}>(`/conversations/${c.id}/messages?markRead=false&limit=100&offset=0`,{headers:{Authorization:`Bearer ${props.token}`}})));letters.value=rows.flatMap(r=>r.items.filter(m=>m.kind==='opening'&&m.mine).map(m=>m.content))}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
onMounted(()=>{void load();if(props.person){const p=props.person;visits.value=[{id:p.id,displayName:p.displayName,avatar:p.avatar,status:p.status},...visits.value.filter(v=>v.id!==p.id)]}})
const title=computed(()=>view.value==='edit'?'Edit profile':view.value==='public'?'Profile':view.value==='connections'?kind.value:view.value==='visitors'?'Visitors':view.value==='letters'?'My letters':'My little corner')
function back(){error.value='';if(sheet.value){sheet.value=['archive','remove','crop'].includes(sheet.value)?'gallery':'';return}if(['profile','public'].includes(view.value))emit('close');else view.value='profile'}
function edit(){draft.value={...profile.value};view.value='edit';error.value=''}
function save(){const age=Number(draft.value.age);if(!draft.value.name.trim()||!Number.isInteger(age)||age<18||age>100){error.value='Enter a name and an age between 18 and 100.';return}Object.assign(profile.value,{name:draft.value.name.trim(),age,city:draft.value.city.trim()||'Somewhere',zodiac:draft.value.zodiac.trim(),bio:draft.value.bio});view.value='profile';notice.value='Profile saved on this device.'}
function removePhoto(){const p=profile.value.slots[remove.value]!;profile.value.archive.push({...p,position:remove.value});profile.value.slots[remove.value]=null;if(profile.value.selected===p.id)profile.value.selected=profile.value.slots.find(Boolean)?.id||'';sheet.value='gallery'}
function restore(i:number){const p=profile.value.archive[i]!;const target=!profile.value.slots[p.position]?p.position:profile.value.slots.findIndex(s=>!s);if(target<0){error.value='Remove a photo first to make space.';return}profile.value.slots[target]=p;profile.value.archive.splice(i,1);if(!profile.value.selected)profile.value.selected=p.id;sheet.value='gallery'}
function pick(i:number){position.value=i;file.value!.value='';file.value!.click()}
async function upload(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(!f)return;const img=new Image();const url=URL.createObjectURL(f);img.onload=async()=>{image.value=img;zoom.value=1;sheet.value='crop';await nextTick();draw();URL.revokeObjectURL(url)};img.onerror=()=>{error.value='This photo could not be opened.';URL.revokeObjectURL(url)};img.src=url}
function draw(){const c=canvas.value!,img=image.value!,scale=Math.max(c.width/img.width,c.height/img.height)*zoom.value;c.getContext('2d')!.drawImage(img,(c.width-img.width*scale)/2,(c.height-img.height*scale)/2,img.width*scale,img.height*scale)}
function saveAvatar(){const p={id:crypto.randomUUID(),src:canvas.value!.toDataURL('image/jpeg',.85),position:position.value};profile.value.slots[position.value]=p;profile.value.selected=p.id;sheet.value='';notice.value='Avatar saved on this device.'}
async function follow(){if(!props.person||props.person.status!=='open'||busy.value)return;busy.value=true;error.value='';try{await api(`/conversations/${props.person.id}`,{method:'PATCH',headers:{Authorization:`Bearer ${props.token}`,'Content-Type':'application/json'},body:JSON.stringify({following:!followed.value})});followed.value=!followed.value}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>
<template>
<SettingsFlow v-if="settingsOpen" @security="emit('security')" @close="settingsOpen=false" />
<ProfileFlow v-if="selectedPerson" :token="token" :person="selectedPerson" @close="selectedPerson=undefined;load()" @chat="selectedChat=selectedPerson;selectedPerson=undefined" @safety="selectedChat=selectedPerson;selectedPerson=undefined" />
<ChatFlow v-if="selectedChat" :token="token" :conversation="selectedChat" @close="selectedChat=undefined;load()" @collect="selectedChat=undefined;notice='Collect your reply from Messages to continue.'" />
<section v-show="!selectedPerson&&!selectedChat" class="d4-profile" @keydown.esc="back">
<header><button id="page-back" aria-label="Back" @click="back">‹</button><h1>{{title}}</h1><button v-if="person" id="public-more" aria-label="Profile options" @click="sheet='safety'">•••</button><button v-else id="open-settings" :aria-label="t('settings')" @click="settingsOpen=true"><img :src="asset('08-interface-icons/icon-settings-light-24')" width="24" height="24" alt=""></button></header>
<p v-if="error" role="alert" class="d4-error">{{error}}</p><p v-if="notice" role="status" class="d4-note">{{notice}}</p>
<div class="d4-body" :key="view">
<template v-if="view==='profile'"><div class="profile-hero"><button id="edit-avatar" aria-label="Change avatar" @click="sheet='gallery'"><img :src="own" alt="Your avatar"><span>▣</span></button><button id="edit-profile" @click="edit"><strong>{{profile.name}}</strong></button><p>{{profile.age}} · {{profile.zodiac?profile.zodiac+' · ':''}}{{profile.city}}</p><p>{{profile.bio}}</p></div><div class="profile-counters"><button id="following" @click="kind='Following';view='connections'">{{following.length}}<small>Following</small></button><button id="followers" @click="kind='Followers';view='connections'">0<small>Followers</small></button><button id="likes" @click="sheet='likes'">0<small>Likes</small></button><button id="profile-visitors" @click="view='visitors'">◷<small>Visitors ›</small></button></div><MomentsFlow :token="token" /><p class="d4-note">Profile and avatar changes are saved on this device. Profile sync is not available yet.</p><button id="profile-letters" class="d4-row" @click="view='letters'">My letters <span>›</span></button></template>
<template v-else-if="view==='edit'"><form @submit.prevent="save" novalidate><label>Nickname<input id="edit-name" v-model="draft.name" maxlength="24"></label><label>Age<input id="edit-age" v-model="draft.age" type="number" min="18" max="100" :aria-invalid="!!error"></label><label>City<input id="edit-city" v-model="draft.city" maxlength="40"></label><label>Zodiac (optional)<input id="edit-zodiac" v-model="draft.zodiac" maxlength="24"></label><label>About me<textarea id="edit-bio" v-model="draft.bio" maxlength="200"></textarea></label><button id="change-avatar" type="button" class="d4-row" @click="sheet='gallery'">Change avatar</button><button id="save-profile" class="primary">Save changes</button></form></template>
<template v-else-if="view==='public'"><div class="profile-hero"><button id="public-avatar" aria-label="View profile photo" @click="largePhoto=photo;sheet='photo'"><img :src="photo" :alt="person!.displayName"></button><h2>{{person!.displayName}}</h2><p>{{[person!.age,person!.zodiac,person!.city].filter(Boolean).join(' · ')}}</p><p>{{person!.bio}}</p></div><div class="d4-cards" v-if="person!.cards?.length"><button v-for="src in person!.cards" :key="src" @click="largePhoto=src;sheet='photo'"><img :src="src" alt="Image card"></button></div><h2>Moments</h2><article v-for="m in person!.moments" :key="m.id" class="d4-moment"><p>{{m.text}}</p><button @click="largePhoto=m.src;sheet='photo'"><img :src="m.src" alt="Moment photo"></button></article><p v-if="!person!.moments?.length" class="d4-empty">No moments yet.</p><div class="d4-public-actions"><p v-if="person!.status!=='open'">Following unlocks after they reply.</p><button id="public-follow" class="d4-row" :disabled="person!.status!=='open'||busy" @click="follow">{{followed?'✓ Following':'＋ Follow'}}</button><button id="public-chat" class="primary" @click="emit('chat')">Chat</button></div></template>
<template v-else-if="view==='connections'"><button v-for="c in kind==='Following'?following:[]" :key="c.id" class="d4-row" :data-connection="c.id" @click="selectedPerson=c">{{c.displayName}} <span>›</span></button><p v-if="kind==='Followers'||!following.length" class="d4-empty">{{kind==='Following'?'No following yet.':'No followers yet.'}}</p><p v-if="kind==='Followers'" class="d4-note">Follower sync is not available yet.</p></template>
<template v-else-if="view==='visitors'"><div class="d4-tabs"><button :aria-pressed="!outgoing" @click="outgoing=false">Visited me</button><button :aria-pressed="outgoing" @click="outgoing=true">I visited</button></div><button v-for="c in outgoing?visits:[]" :key="c.id" class="d4-row" @click="selectedPerson=c">{{c.displayName}} <span>›</span></button><p v-if="!outgoing||!visits.length" class="d4-empty">{{outgoing?'No visits yet.':'No visitors yet.'}}</p></template>
<template v-else><p v-if="loading">Loading letters…</p><p v-else-if="!letters.length" class="d4-empty">No letters yet.</p><article v-for="(letter,i) in letters" :key="i" class="d4-moment">{{letter}}</article></template>
</div>
<input ref="file" type="file" accept="image/*" hidden @change="upload">
<Transition name="d4-sheet"><div v-if="sheet" class="d4-veil" @click.self="back"><section role="dialog" aria-modal="true" :aria-label="sheet" class="d4-sheet"><button class="d4-close" aria-label="Close" @click="back">×</button>
<template v-if="sheet==='gallery'"><h2>Choose an avatar</h2><div class="avatar-gallery"><div v-for="(p,i) in profile.slots" :key="i" class="avatar-slot"><template v-if="p"><button class="avatar-option" :data-avatar-slot="i" :aria-pressed="profile.selected===p.id" @click="profile.selected=p.id;sheet=''"><img :src="p.src" :alt="`Avatar ${i+1}`"><span v-if="profile.selected===p.id">✓</span></button><button class="avatar-remove" :data-remove-avatar="i" :aria-label="`Remove photo ${i+1}`" @click="remove=i;sheet='remove'">×</button></template><button v-else class="avatar-empty" :data-upload-avatar="i" :aria-label="`Upload a photo ${i+1}`" @click="pick(i)">▣<small>Not uploaded</small></button></div></div><button id="upload-avatar" class="primary" :disabled="profile.slots.every(Boolean)" @click="pick(profile.slots.findIndex(s=>!s))">Upload a photo</button><button v-if="profile.archive.length" id="removed-avatars" class="d4-row" @click="sheet='archive'">Recently removed ({{profile.archive.length}})</button></template>
<template v-else-if="sheet==='remove'"><h2>Remove this photo?</h2><p>You can restore removed photos from Recently removed.</p><button id="confirm-remove-avatar" class="primary" @click="removePhoto">Remove photo</button><button class="d4-row" @click="sheet='gallery'">Cancel</button></template>
<template v-else-if="sheet==='archive'"><h2>Recently removed</h2><p>Restore a photo to an empty position.</p><div class="avatar-gallery"><button v-for="(p,i) in profile.archive" :key="p.id" class="avatar-option" :data-restore-avatar="i" :aria-label="`Restore ${i+1}`" @click="restore(i)"><img :src="p.src" alt="Removed avatar"></button></div><button id="avatar-gallery-back" class="d4-row" @click="sheet='gallery'">Back</button></template>
<template v-else-if="sheet==='crop'"><h2>Crop avatar</h2><canvas id="avatar-canvas" ref="canvas" width="320" height="320"></canvas><label>Zoom<input id="avatar-zoom" v-model="zoom" type="range" min="1" max="3" step=".01" @input="draw"></label><button id="save-avatar" class="primary" @click="saveAvatar">Use photo</button></template>
<template v-else-if="sheet==='photo'"><img class="d4-photo" :src="largePhoto" alt="Profile photo"></template>
<template v-else-if="sheet==='likes'"><h2>Likes</h2><p>♡ Moments <strong>0</strong></p><p>▧ Image cards <strong>0</strong></p><button class="primary" @click="sheet=''">Got it</button></template>
<template v-else-if="sheet==='safety'"><h2>Keep your little corner safe</h2><button id="safety-report" class="d4-row" @click="emit('safety','report')">Report</button><button id="safety-block" class="d4-row" @click="emit('safety','block')">Block</button></template>
</section></div></Transition>
</section>
</template>
<style scoped>
.d4-profile{position:absolute;inset:0;z-index:30;background:#0d1713;color:#e4efd9;display:flex;flex-direction:column;padding-top:48px}.d4-profile header{display:flex;align-items:center;justify-content:space-between;padding:0 20px;height:56px;flex-shrink:0}.d4-profile header button{background:none;border:0;color:#b8ccb0;font-size:26px}.d4-profile h1{font-size:19px;font-weight:500}.d4-profile h2{font-size:17px;font-weight:500}.d4-body{overflow:auto;padding:12px 24px 40px;flex:1;animation:d4-open .3s ease-out}.d4-profile button{cursor:pointer}.d4-profile button:disabled{opacity:.4;cursor:default}.profile-hero{text-align:center;padding:20px 0}.profile-hero button{display:block;margin:auto;background:none;border:0;color:inherit;position:relative}.profile-hero img{width:88px;height:88px;object-fit:cover;border-radius:50%;border:2px solid #b5fa7055}.profile-hero span{position:absolute;right:4px;bottom:0;border-radius:50%;background:#b5fa70;color:#183020;padding:5px}.profile-hero strong{display:inline-block;font-size:18px;font-weight:500;margin-top:14px}.profile-hero p{font-size:12px;color:#a2b797;line-height:1.8}.profile-counters{display:flex;justify-content:space-between;border-bottom:1px solid #c8e4b31a;padding:10px 0 26px}.profile-counters button{border:0;background:none;color:#d0e2c4;font-size:20px}.profile-counters small{display:block;font-size:11px;margin-top:5px;color:#a2b797}.d4-moment{padding:16px;background:#233729;border-radius:14px;margin:12px 0}.d4-moment button,.d4-cards button{padding:0;background:none;border:0}.d4-moment img{width:100%;border-radius:12px}.d4-cards img{width:136px;height:180px;object-fit:cover;border-radius:14px}.d4-cards{gap:12px;overflow:auto;min-height:140px;display:flex;align-items:center;color:#81947a;font-size:13px}.d4-note{font-size:11px;color:#81947a;line-height:1.8;padding:0 16px}.d4-error{color:#edb39f;font-size:13px;padding:0 24px}.d4-row{display:block;width:100%;text-align:left;border:0;border-bottom:1px solid #b8ccb015;padding:18px 4px;color:#d0e2c4;background:transparent;font-size:14px}.d4-row span{float:right}.d4-profile label{display:block;color:#a2b797;font-size:12px;margin:16px 0}.d4-profile input:not([type=range]),.d4-profile textarea{display:block;width:100%;margin-top:8px;background:#14271e;border:1px solid #b8ccb022;border-radius:12px;color:#e4efd9;padding:14px;font:inherit;font-size:15px}.d4-profile textarea{height:100px;resize:vertical}.d4-profile .primary{width:100%;margin-top:16px;min-height:48px;border:0;border-radius:24px}.d4-empty{text-align:center;padding:70px 0;color:#81947a;font-size:14px}.d4-public-actions{margin-top:60px}.d4-public-actions p{font-size:12px;color:#a2b797}.d4-tabs{display:flex;gap:16px}.d4-tabs button{background:none;color:#a2b797;border:0;padding:14px}.d4-tabs [aria-pressed=true]{color:#b5fa70;border-bottom:2px solid}.d4-veil{position:absolute;inset:0;background:#030805b8;display:flex;align-items:flex-end;z-index:40;backdrop-filter:blur(5px)}.d4-sheet{position:relative;background:#1c2c22;width:100%;padding:26px 22px 36px;border-radius:26px 26px 0 0;max-height:88%;overflow:auto;border:1px solid #b8ccb018}.d4-sheet p{font-size:13px;color:#a2b797;line-height:1.8}.d4-close{position:absolute;right:14px;top:12px;color:#a2b797;border:0;background:none;font-size:26px}.avatar-gallery{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:16px 0 24px}.avatar-slot{position:relative;min-width:0}.avatar-option,.avatar-empty{position:relative;padding:0;width:100%;aspect-ratio:1;border-radius:16px;background:#1a2a20;border:1px solid #ffffff11;color:#a2b797;overflow:hidden}.avatar-option img{width:100%;height:100%;object-fit:cover}.avatar-option[aria-pressed=true]{border:2px solid #b5fa70}.avatar-option span{position:absolute;bottom:0;right:0;background:#b5fa70;color:#19362b;border-radius:50%;padding:2px 5px}.avatar-remove{position:absolute;right:-5px;top:-5px;border:0;border-radius:50%;background:#52684e;color:#e4efd9;width:24px;height:24px}.avatar-empty small{display:block;font-size:8px;margin-top:4px}.d4-photo{width:100%;max-height:65vh;object-fit:contain}#avatar-canvas{width:100%;border-radius:50%;display:block;margin:20px auto}.d4-sheet input[type=range]{display:block;width:100%;accent-color:#b5fa70}.d4-sheet-enter-active,.d4-sheet-leave-active{transition:opacity .25s}.d4-sheet-enter-active .d4-sheet,.d4-sheet-leave-active .d4-sheet{transition:transform .25s}.d4-sheet-enter-from,.d4-sheet-leave-to{opacity:0}.d4-sheet-enter-from .d4-sheet,.d4-sheet-leave-to .d4-sheet{transform:translateY(70px)}@keyframes d4-open{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:translateY(0)}}
</style>
